function isStrictDirective(line) {
  const t = line.trim();
  return (
    t === "'use strict'" ||
    t === "'use strict';" ||
    t === '"use strict"' ||
    t === '"use strict";'
  );
}

function hostOnlyApis(specApis, hostApis) {
  const spec = new Set(specApis);
  return hostApis.filter((name) => !spec.has(name));
}

